Lemma fs6_scan : forall (Q : machine_state -> Prop) (m : mem) (FSB h : Z) (fl : list Z) (j : nat)
    ra sp gp tp t1 t2 s0 s1 a1 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc,
  fs_flags FSB 6 m fl -> Z.of_nat (length fl) = 256 -> flags_ok 6 fl ->
  0 <= h < 2 ^ 61 -> 0 < FSB -> fl_base FSB 6 + 256 <= 2 ^ 47 ->
  scan_from fl 256 h 256 = Some j ->
  (forall t0 a0, evt asegs Q
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (Z_to_bv 64 (h + Z.of_nat j)) (Z_to_bv 64 (fl_base FSB 6))
               (Z_to_bv 64 (fl_base FSB 6 + (h + Z.of_nat j) mod 256)) (Z_to_bv 64 255) a6 (Z_to_bv 64 ((h + Z.of_nat j) mod 256))
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xacd30) fc None m (seg_rom asegs))) ->
  mem_inv asegs m ->
  forall (k : nat), (k <= j)%nat -> forall t0 a5 a7,
  evt asegs Q
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (256 - Z.of_nat (j - k))) a1 (Z_to_bv 64 (h + Z.of_nat (j - k)))
             (Z_to_bv 64 (fl_base FSB 6)) a5 (Z_to_bv 64 255) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
