Definition sm6_post (ra sp gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (FSB h : Z) (fl : list Z) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (j : nat) (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem) junk1 junk2,
    ms' = MS (mkR ra sp gp (Z_to_bv 64 tpA) t0' t1' t2' s0 s1 (Z_to_bv 64 (frame_addr FSB 6 ((h + Z.of_nat j) mod 256)))
                  a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (sm_W 6 FSB ((h + Z.of_nat j) mod 256) (bv_unsigned sp)) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ (j < 256)%nat /\ nth (Z.to_nat ((h + Z.of_nat j) mod 256)) fl 1 = 0
    /\ fs_hint FSB 6 m' (h + Z.of_nat j + 1) /\ fs_const FSB m'
    /\ fs_flags FSB 6 m' (upd fl (Z.to_nat ((h + Z.of_nat j) mod 256)) 1)
